    elif c==')':
        j=st.pop(); pt[i]=j; pt[j]=i
pairs_list=[(i,pt[i]) for i in range(n) if pt[i]>i]
unpaired=[i for i in range(n) if target[i]=='.']
# stem closing pairs (outermost of each contiguous stem run)
strong_close={(5,84),(10,29),(30,79),(36,73),(40,51),(54,69)}
# the lonely pair (13,27) - try G-C always
lonely={(13,27)}
PAIRS=[('G','C'),('C','G'),('A','U'),('U','A'),('G','U'),('U','G')]

def fold(seq):
    fc=RNA.fold_compound(seq)
    ss,mfe=fc.mfe()
    return ss,mfe

def dist(ss):
    sst=[]; spt=[-1]*n
    for i,c in enumerate(ss):
        if c=='(': sst.append(i)
        elif c==')':
            j=sst.pop(); spt[i]=j; spt[j]=i
    miss=0;spur=0
    for i in range(n):
        if pt[i]>i and spt[i]!=pt[i]: miss+=1
        if spt[i]>i and pt[i]!=spt[i]: spur+=1
    return miss+spur

def seed(s):
    random.seed(s)
    seq=['A']*n
    for i,j in pairs_list:
        if (i,j) in lonely:
            a,b=('G','C') if random.random()<0.7 else ('C','G')
        elif (i,j) in strong_close:
            a,b=('G','C') if random.random()<0.6 else ('C','G')
        else:
            a,b=random.choice(PAIRS)
        seq[i]=a; seq[j]=b
    return seq

def worker(s):
    TL=40
    cur=seed(s)
    ss,_=fold(''.join(cur)); cur_d=dist(ss)
    best=list(cur); best_d=cur_d
    t0=time.time()
    while time.time()-t0<TL and best_d>0:
        r=random.random()
        changes=[]
        if r<0.6:
            i,j=random.choice(pairs_list)
            a,b=random.choice(PAIRS)
            changes.append((i,j,cur[i],cur[j]))
            cur[i]=a;cur[j]=b
        elif r<0.85:
            # mutate a pair to G-C
            i,j=random.choice(pairs_list)
            changes.append((i,j,cur[i],cur[j]))
            a,b=('G','C') if random.random()<0.5 else ('C','G')
            cur[i]=a;cur[j]=b
        else:
            k=random.choice(unpaired)
            changes.append((k,None,cur[k],None))
            cur[k]=random.choice('ACGU')
        ss,_=fold(''.join(cur)); nd=dist(ss)
        if nd<cur_d or (nd==cur_d and random.random()<0.4):
            cur_d=nd
            if nd<best_d:
                best_d=nd; best=list(cur)
        else:
            for (i,j,oi,oj) in changes:
                cur[i]=oi
                if j is not None: cur[j]=oj
    return best_d,''.join(best)

if __name__=='__main__':
    with Pool(32) as p:
        res=p.map(worker, range(64))
    res.sort()
    for d,s in res[:3]:
        print('d=',d, s, file=sys.stderr)
    print(res[0][1])
